// eslint-disable-next-line @typescript-eslint/no-require-imports
const { DataTypes } = require('sequelize');
// eslint-disable-next-line @typescript-eslint/no-require-imports
const { sequelize } = require('../database'); // Assurez-vous que vous utilisez la bonne importation

const Sujet = sequelize.define('Sujet', {
  idSujet: { 
    type: DataTypes.INTEGER, 
    primaryKey: true, 
    autoIncrement: true, // Auto-incrémentation
    allowNull: false 
  },
  titre: { type: DataTypes.STRING(50), allowNull: false },

  idEncadrant: { 
    type: DataTypes.STRING(50), 
    allowNull: false,
    references: {
      model: 'Encadrant', // Nom de la table Encadrant
      key: 'idEncadrant', // Clé primaire de la table Encadrant
    },
  },
}, {  
  timestamps: false,
  tableName: 'Sujet' 
});

module.exports = Sujet;
