const nodemailer = require('nodemailer');

const sendEmail = async (req, res) => {
  const { email, password } = req.body;

  const transporter = nodemailer.createTransport({
    service: "gmail",
    auth: {
      user: process.env.EMAIL_USER,
      pass: process.env.EMAIL_PASS,
    },
  });

  const mailOptions = {
    from: process.env.EMAIL_USER,
    to: email,
    subject: "Informations de Connexion à l'App",
    text: `Votre mot de passe est ${password}. Vous pouvez vous connecter en suivant ce lien: http://localhost:3000`,
  };

  try {
    await transporter.sendMail(mailOptions);
    res.status(200).json({ message: "Email envoyé avec succès" });
  } catch (error) {
    console.error("Erreur lors de l'envoi de l'email :", error); // Afficher l'erreur dans la console
    res.status(500).json({ message: "Erreur lors de l'envoi de l'email", error: error.message });
  }
};

module.exports = { sendEmail };