// eslint-disable-next-line @typescript-eslint/no-require-imports
const Groupe = require('../models/Groupe');
// eslint-disable-next-line @typescript-eslint/no-require-imports
const Tuteur = require('../models/Tuteur');
// eslint-disable-next-line @typescript-eslint/no-require-imports
const Sujet = require('../models/Sujet');
// eslint-disable-next-line @typescript-eslint/no-require-imports
const Etudiant = require('../models/Etudiant');

class GroupeRepository {
  constructor() {
    this.Groupe = Groupe;
    this.Etudiant = Etudiant;
    this.Tuteur=Tuteur;
    this.Sujet=Sujet;
  }

  // Create a new group
  async createGroupe(nomGroupe, annee) {
    try {
      const groupe = await this.Groupe.create({ nomGroupe, annee });
      return groupe;
    } catch (error) {
      throw new Error(`Error creating group: ${error.message}`);
    }
  }

    async findGroupeById(idGroupe) {
      try {
        console.log("Recherche du groupe avec l'ID:", idGroupe);  // Log de l'ID reçu
        const groupe = await this.Groupe.findByPk(idGroupe, {
          include: [{ model: this.Etudiant, as: 'etudiants' }],
        });
    
        if (!groupe) {
          console.log(`Aucun groupe trouvé avec l'ID ${idGroupe}`);
          return null;  // Aucun groupe trouvé
        }
    
        return groupe;
      } catch (error) {
        throw new Error(`Erreur lors de la recherche du groupe par ID: ${error.message}`);
      }
    }
    
    

  // Update a group
  async updateGroupe(idGroupe, nomGroupe, annee) {
    try {
      const groupe = await this.Groupe.findByPk(idGroupe);
      if (groupe) {
        groupe.nomGroupe = nomGroupe;
        groupe.annee = annee;
        await groupe.save();
        return groupe;
      }
      return null;
    } catch (error) {
      throw new Error(`Error updating group: ${error.message}`);
    }
  }
    async deleteGroupe(idGroupe) {
      try {
        console.log("Repository: Tentative de suppression du groupe", idGroupe);
    
        // Recherche du groupe dans la base de données
        const groupe = await this.Groupe.findByPk(idGroupe);
        if (!groupe) {
          console.log("Repository: Groupe non trouvé", idGroupe);
          return false;
        }
    
        // Suppression du groupe
        console.log("Repository: Suppression du groupe", idGroupe);
        await groupe.destroy();
        console.log("Repository: Groupe supprimé avec succès", idGroupe);
    
        return true;
      } catch (error) {
        console.error("Repository: Erreur lors de la suppression du groupe:", error);
        throw new Error(`Erreur lors de la suppression du groupe: ${error.message}`);
      }
    }
    
   // Find all groups
   async findAllGroupeset() {
    try {
      const groupes = await this.Groupe.findAll({
        include: [{ model: this.Etudiant, as: 'etudiants' }],
      });
      return groupes;
    } catch (error) {
      throw new Error(`Error finding all groups: ${error.message}`);
    }
  }

  // Add a student to a group
  async addStudentToGroupe(idGroupe, idEtudiant) {
    try {
      const etudiant = await this.Etudiant.findByPk(idEtudiant);
      if (etudiant) {
        etudiant.idGroupe = idGroupe;
        await etudiant.save();
        return etudiant;
      }
      return null;
    } catch (error) {
      throw new Error(`Error adding student to group: ${error.message}`);
    }
  }

  // Remove a student from a group
  async removeStudentFromGroupe(idEtudiant) {
    try {
      const etudiant = await this.Etudiant.findByPk(idEtudiant);
      if (etudiant) {
        etudiant.idGroupe = null;
        await etudiant.save();
        return etudiant;
      }
      return null;
    } catch (error) {
      throw new Error(`Error removing student from group: ${error.message}`);
    }
  }


  async createGroupe(nomGroupe, annee) {
    try {
      console.log('Creating group with:', { nomGroupe, annee });
      const groupe = await Groupe.create({ nomGroupe, annee });
      console.log('Group created successfully:', groupe);
      return {
        idGroupe: groupe.idGroupe,
        nomGroupe: groupe.nomGroupe,
        annee: groupe.annee
      };
    } catch (error) {
      console.error('Error creating group:', error);
      if (error.name === 'SequelizeUniqueConstraintError') {
        throw new Error('Group name must be unique.');
      } else if (error.name === 'SequelizeValidationError') {
        throw new Error('Invalid input data.');
      } else {
        throw error;
      }
    }
  }
    
  

  async findAllWithStudents() {
    return await Groupe.findAll({
      include: ['etudiants'] // Include associated students
    });
  }
  
  async affecterSujetEtTuteur(idGroupe, idTuteur, idSujet) {
    try {
      const groupe = await this.Groupe.findByPk(idGroupe);
      if (!groupe) {
        throw new Error('Groupe non trouvé');
      }
  
      // Affecter le tuteur et le sujet
      groupe.idTuteur = idTuteur; // idTuteur reste en string
      groupe.idSujet = idSujet;   // idSujet reste en entier
      await groupe.save();
  
      return groupe;
    } catch (error) {
      throw new Error(`Erreur lors de l'affectation: ${error.message}`);
    }
  }

  async findAllGroupes() {
    return await Groupe.findAll();
  }


  async findAllGroupesWithDetails() {
    const groupes = await Groupe.findAll({
      include: [
        { model: Tuteur, as: 'tuteur', attributes: ['nom','prenom'] }, // Utiliser l'alias 'tuteur'
        { model: Sujet, as: 'sujet', attributes: ['titre'] }, // Utiliser l'alias 'sujet'
        { model: Etudiant, as: 'etudiants', attributes: ['nom','prenom'] }, // Utiliser l'alias 'etudiants'
      ],
    });

    // Formater les résultats
    return groupes.map(groupe => ({
      groupeNom: groupe.nomGroupe, // Utiliser 'nomGroupe' au lieu de 'nom'
      tuteurNom: groupe.tuteur ? `${groupe.tuteur.nom} ${groupe.tuteur.prenom}` : 'Non assigné', // Afficher le nom et prénom du tuteur
      sujetTitre: groupe.sujet ? groupe.sujet.titre : 'Non assigné', // Vérifier si le sujet existe
      etudiants: groupe.etudiants.map(etudiant => `${etudiant.nom} ${etudiant.prenom}`), // Afficher le nom et prénom des étudiants
    }));
  }


  async assignTuteurAndSujet(groupeId, tuteurId, sujetId) {
    console.log(`Assigning tuteur ${tuteurId} and sujet ${sujetId} to groupe ${groupeId}`);
    const groupe = await Groupe.findByPk(groupeId);
    if (!groupe) throw new Error('Groupe non trouvé');

    groupe.idTuteur = tuteurId;
    groupe.idSujet = sujetId;
    await groupe.save();

    console.log('Groupe updated successfully:', groupe);
    return groupe;
  }
//akhir haja zadt farah

  
  // ✅ Compter le nombre de groupes affectés à un sujet
  async countGroupesAvecSujet(idSujet) {
    try {
      return await this.Groupe.count({ where: { idSujet } });
    } catch (error) {
      throw new Error(`Erreur lors du comptage des groupes avec ce sujet: ${error.message}`);
    }
  }

  // ✅ Trouver un groupe associé à un tuteur
  async findGroupeByTuteur(idTuteur) {
    try {
      return await this.Groupe.findOne({ where: { idTuteur } });
    } catch (error) {
      throw new Error(`Erreur lors de la recherche du groupe par tuteur: ${error.message}`);
    }
  }
  // Récupérer un groupe par ID
  async findGroupeByIdst(idGroupe) {
    try {
      const groupe = await this.Groupe.findByPk(idGroupe, {
        include: [
          { model: this.Etudiant, as: 'etudiants' },
          { model: this.Tuteur, as: 'tuteur' },
          { model: this.Sujet, as: 'sujet' }
        ],
      });
      if (!groupe) {
        return null;
      }
      return groupe;
    } catch (error) {
      throw new Error(`Erreur lors de la recherche du groupe par ID: ${error.message}`);
    }
  }

  // Trouver tous les groupes
  async findAllGroupesst() {
    try {
      const groupes = await this.Groupe.findAll({
        include: [
          { model: this.Etudiant, as: 'etudiants' },
          { model: this.Tuteur, as: 'tuteur' },
          { model: this.Sujet, as: 'sujet' }
        ],
      });
      return groupes;
    } catch (error) {
      throw new Error(`Erreur lors de la récupération de tous les groupes: ${error.message}`);
    }
  }
  async updateGroupeSujetTuteur(idGroupe, idSujet, idTuteur) {
    try {
      console.log(`Repository: Modification du groupe ${idGroupe} - Nouveau sujet: ${idSujet}, Nouveau tuteur: ${idTuteur}`);
      
      // Recherche du groupe à modifier
      const groupe = await Groupe.findByPk(Number(idGroupe));
      
      if (!groupe) {
        return null;
      }
      
      // Préparation des données à mettre à jour
      const updateData = {};
      
      // Vérification que le sujet existe si un nouveau sujet est spécifié
      if (idSujet !== undefined) {
        const sujet = await Sujet.findByPk(Number(idSujet));
        if (!sujet) {
          throw new Error("Sujet non trouvé");
        }
        updateData.idSujet = Number(idSujet);
      }
      
      // Vérification que le tuteur existe si un nouveau tuteur est spécifié
      if (idTuteur !== undefined) {
        const tuteur = await Tuteur.findByPk(idTuteur);
        if (!tuteur) {
          throw new Error("Tuteur non trouvé");
        }
        updateData.idTuteur = idTuteur;
      }
      
      // Mise à jour du groupe avec les données validées
      await groupe.update(updateData);
      
      // Récupération du groupe mis à jour avec ses relations
      // Utilisons une approche qui évite de spécifier les champs explicitement
      const groupeMisAJour = await Groupe.findByPk(Number(idGroupe), {
        include: [
          {
            model: Tuteur,
            as: 'tuteur'
          },
          {
            model: Sujet,
            as: 'sujet'
          },
          {
            model: Etudiant,
            as: 'etudiants'
          }
        ]
      });
      
      return groupeMisAJour;
    } catch (error) {
      console.error("Erreur dans le repository lors de la modification du groupe:", error);
      throw error;
    }
  }
  async removeTuteurAndSujetFromGroupe(idGroupe) {
    try {
      console.log("Suppression des affectations pour le groupe ID:", idGroupe);
      const groupe = await Groupe.findByPk(idGroupe);
  
      if (!groupe) {
        console.log("Groupe non trouvé !");
        return false;
      }
  
      // Mettre à null l'id du tuteur et l'id du sujet
      groupe.idTuteur = null;
      groupe.idSujet = null;
      await groupe.save();
  
      console.log("Tuteur et sujet supprimés !");
      return true;
    } catch (error) {
      console.error("Erreur dans le repository lors de la suppression du tuteur et du sujet:", error);
      throw error;
    }
  }
}

module.exports =  new GroupeRepository();
