// eslint-disable-next-line @typescript-eslint/no-require-imports
const tuteurRepository = require('../repositories/TuteurRepository');
// eslint-disable-next-line @typescript-eslint/no-require-imports
const sujetRepository = require('../repositories/SujetRepository');
// eslint-disable-next-line @typescript-eslint/no-require-imports
const groupeRepository = require('../repositories/GroupeRepository');
class AffectationService {
  async assignTuteursAndSujetsAleatoires() {
    try {
      // Récupérer tous les tuteurs, sujets et groupes
      const [tuteurs, sujets, groupes] = await Promise.all([
        tuteurRepository.getAllTuteurs(),
        sujetRepository.getAllSujets(),
        groupeRepository.findAllGroupes(),
      ]);

      // Vérifier s'il y a assez de tuteurs, sujets et groupes
      if (tuteurs.length === 0 || sujets.length === 0 || groupes.length === 0) {
        throw new Error('Pas assez de tuteurs, sujets ou groupes pour effectuer l\'affectation');
      }

      // Filtrer les tuteurs disponibles
      const tuteursDisponibles = tuteurs.filter(tuteur => !tuteur.isAssigned);

      if (tuteursDisponibles.length === 0) {
        throw new Error('Tous les tuteurs sont déjà affectés à un groupe');
      }

      // Assigner les tuteurs et les sujets aux groupes
      for (const groupe of groupes) {
        if (tuteursDisponibles.length === 0) {
          throw new Error('Plus de tuteurs disponibles pour affectation');
        }

        // Sélectionner un tuteur aléatoire
        const randomTuteurIndex = Math.floor(Math.random() * tuteursDisponibles.length);
        const randomTuteur = tuteursDisponibles[randomTuteurIndex];

        // Filtrer les sujets disponibles (ceux qui n'ont pas atteint leur limite)
        const sujetsDisponibles = await Promise.all(
          sujets.map(async (sujet) => {
            const count = await sujetRepository.countGroupesBySujet(sujet.idSujet);
            return count < 3 ? sujet : null;
          })
        ).then(results => results.filter(sujet => sujet !== null));

        if (sujetsDisponibles.length === 0) {
          throw new Error('Tous les sujets ont atteint leur limite d\'affectation');
        }

        // Sélectionner un sujet aléatoire parmi les sujets disponibles
        const randomSujetIndex = Math.floor(Math.random() * sujetsDisponibles.length);
        const randomSujet = sujetsDisponibles[randomSujetIndex];

        // Assigner le tuteur et le sujet au groupe
        await groupeRepository.assignTuteurAndSujet(groupe.idGroupe, randomTuteur.idTuteur, randomSujet.idSujet);

        // Retirer le tuteur assigné de la liste des disponibles
        tuteursDisponibles.splice(randomTuteurIndex, 1);
      }

      // Récupérer les groupes avec les détails complets
      const groupesAvecDetails = await groupeRepository.findAllGroupesWithDetails();
      return groupesAvecDetails;
    } catch (error) {
      console.error('Erreur dans assignTuteursAndSujetsAleatoires:', error);
      throw error;
    }
  }
}

module.exports = AffectationService;